{
  "title": "A Food-Lover's Mexico City Ramble",
  "summary": "A gentler day built around markets, snacks and a proper sit-down meal, with a little history and a leafy stroll in between.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The one must-do we kept, and rightly so: a pocket of Aztec history right in the heart of the city.",
      "must_do_id_note": "Kept from the original plan."
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "A market stop for the street-food curious: stalls, chatter and a proper snack before lunch.",
      "must_do_id_note": "Added to satisfy the request for more food stops."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch with vegetarian plates and a warm, easy pace, right in the same area as the morning stops.",
      "must_do_id_note": "A meal place added to give the day a proper sit-down meal."
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "A short museum visit to round out the day with a little art and a lot of marble.",
      "must_do_id_note": "Kept as a light afternoon activity."
    }
  ]
}
